      const res = await fetch(`/search/suggest.json?q=${encodeURIComponent(q)}&resources[type]=product&resources[limit]=10`);
      if (res.ok) {
        const data = await res.json();
        allResults.push(...data.resources.results.products);
      }
    } catch (e) {
      allResults.push({ error: e.message, query: q });
    }
  }
  return allResults;
});

// Remove duplicates by handle/url
const unique = [];
const seen = new Set();
for (const item of searchResults) {
  if (item.handle && !seen.has(item.handle)) {
    seen.add(item.handle);
    unique.push({
      title: item.title,
      handle: item.handle,
      url: item.url,
      price: item.price
    });
  }
}

