const tabId = 2052873191;

// Search for brown leather jacket on Edikted
const searchResults = await browserjs(tabId, async () => {
  const queries = [
    "brown leather jacket",
    "dark brown leather jacket",
    "oversized leather jacket brown",
    "brown faux leather jacket",
    "brown jacket"
  ];
  const allResults = [];
  for (const q of queries) {
    try {
      const res = await fetch(`/search/suggest.json?q=${encodeURIComponent(q)}&resources[type]=product&resources[limit]=10`);
      if (res.ok) {
        const data = await res.json();
        allResults.push(...data.resources.results.products);
      }
    } catch (e) {
      allResults.push({ error: e.message, query: q });
    }
  }
  return allResults;
});

// Remove duplicates by handle/url
const unique = [];
const seen = new Set();
for (const item of searchResults) {
  if (item.handle && !seen.has(item.handle)) {
    seen.add(item.handle);
    unique.push({
      title: item.title,
      handle: item.handle,
      url: item.url,
      price: item.price
    });
  }
}

console.log("Edikted search results:", JSON.stringify(unique, null, 2));

