const tabId = 2052873191;
const candidateHandles = [
  "s23008_dark-brown",
  "s14833_brown",
  "s21181_brown",
  "s17936_brown",
  "s14969_brown"
];

const results = await browserjs(tabId, async (handles) => {
  const out = [];
  for (const h of handles) {
    try {
      const res = await fetch(`/products/${h}.js`);
      if (res.ok) {
        const d = await res.json();
        out.push({
          title: d.title,
          handle: h,
          price: d.price / 100,
          description: d.description.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
          images: d.images?.slice(0, 2),
          options: d.options,
          variants: d.variants.map(v => ({ title: v.title, available: v.available, price: v.price / 100 }))
        });
      }
    } catch (e) {
      out.push({ handle: h, error: e.message });
    }
  }
  return out;
}, candidateHandles);

console.log(JSON.stringify(results, null, 2));

